        "ru"
      ]
    },
    "live": {
      "type": "string",
      "title": "Rules while Claude edits",
      "description": "warn: check each edit against CLAUDE.md as it lands and tell Claude what it broke; block: check it before it lands and refuse it; off: leave the rules to the review after the turn",
      "default": "warn",
      "options": [
        "warn",
        "block",
        "off"
      ]
    },
    "liveModel": {
